class Shape:
    def area(self):
        pass

class Square(Shape):
    def __init__(self, length) -> None:
        self.length = length

    def area(self):
        return math.pow(self.length, 2)

class Circle(Shape):
    def __init__(self, radius) -> None:
        self.radius = radius

    def area(self):
        return math.pi * math.pow(self.radius, 2)

class AreaManager:
    def __init__(self, shapes=[]) -> None:
        self.shapes = shapes

    def total_area(self):
        return sum(shape.area() for shape in self.shapes)
